From fa4e6ed88768d3b769171988a4ee538db7ec21d9 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 19:17:10 +0100
Subject: [PATCH] daemon: Keep screens on while they are mirrored

Screens dimmed, turned off and locked on idle even while mirrored, which
usually means a presentation is going on. Like notifications already do,
add a screen power management inhibition while any screens overlap.

BUG: 495738
---
 daemon/powerdevilcore.cpp | 38 ++++++++++++++++++++++++++++++++++++++
 daemon/powerdevilcore.h   |  6 ++++++
 2 files changed, 44 insertions(+)

diff --git a/daemon/powerdevilcore.cpp b/daemon/powerdevilcore.cpp
index 33badced8..713946a6f 100644
--- a/daemon/powerdevilcore.cpp
+++ b/daemon/powerdevilcore.cpp
@@ -36,6 +36,8 @@
 #include <QDBusConnection>
 #include <QDBusConnectionInterface>
 #include <QDBusServiceWatcher>
+#include <QGuiApplication>
+#include <QScreen>
 #include <QTimer>

 #include <QDebug>
@@ -174,6 +176,18 @@ void Core::onControllersReady()
     connect(PowerDevil::PolicyAgent::instance(), &PowerDevil::PolicyAgent::screenLockerActiveChanged, this, &Core::onScreenLockerActiveChanged);
     connect(m_suspendController.get(), &SuspendController::resumeFromSuspend, this, &Core::onResumeFromSuspend);

+    // Like notifications, keep the screens on while they're mirrored, as it usually means a presentation is ongoing
+    const QList<QScreen *> screens = qApp->screens();
+    for (const QScreen *screen : screens) {
+        connect(screen, &QScreen::geometryChanged, this, &Core::checkScreensMirrored);
+    }
+    connect(qApp, &QGuiApplication::screenAdded, this, [this](QScreen *screen) {
+        connect(screen, &QScreen::geometryChanged, this, &Core::checkScreensMirrored);
+        checkScreensMirrored();
+    });
+    connect(qApp, &QGuiApplication::screenRemoved, this, &Core::checkScreensMirrored);
+    checkScreensMirrored();
+
     // Initialize the action pool, which may also initialize profile-independent functionality
     refreshActions();

@@ -1281,6 +1295,30 @@ ScreenBrightnessController *Core::screenBrightnessController()
 {
     return m_screenBrightnessController.get();
 }
+
+void Core::checkScreensMirrored()
+{
+    bool mirrored = false;
+    const QList<QScreen *> screens = qApp->screens();
+    for (const QScreen *screen : screens) {
+        for (const QScreen *checkScreen : screens) {
+            if (screen != checkScreen && screen->geometry().contains(checkScreen->geometry())) {
+                mirrored = true;
+                break;
+            }
+        }
+    }
+
+    if (mirrored && !m_screensMirroredInhibit) {
+        qCDebug(POWERDEVIL) << "Screens are mirrored, inhibiting screen power management";
+        m_screensMirroredInhibit =
+            PolicyAgent::instance()->AddInhibition(PolicyAgent::ChangeScreenSettings, i18n("Display Configuration"), i18n("Screens are mirrored"));
+    } else if (!mirrored && m_screensMirroredInhibit) {
+        qCDebug(POWERDEVIL) << "Screens are no longer mirrored, releasing screen power management inhibition";
+        PolicyAgent::instance()->ReleaseInhibition(*m_screensMirroredInhibit);
+        m_screensMirroredInhibit.reset();
+    }
+}
 }

 #include "moc_powerdevilcore.cpp"
diff --git a/daemon/powerdevilcore.h b/daemon/powerdevilcore.h
index 95c8341eb..8a0134089 100644
--- a/daemon/powerdevilcore.h
+++ b/daemon/powerdevilcore.h
@@ -26,6 +26,8 @@
 #include "controllers/suspendcontroller.h"
 #include "powerdevilcore_export.h"

+#include <optional>
+
 namespace KActivities
 {
 class Consumer;
@@ -198,6 +200,9 @@ private:
     QHash<QString, int> m_sessionActivityInhibit;
     QHash<QString, int> m_screenActivityInhibit;

+    // Screen management inhibition while screens are mirrored, e.g. during a presentation
+    std::optional<uint> m_screensMirroredInhibit;
+
     std::unordered_map<QString, std::unique_ptr<Action>> m_actionPool;
     QSet<QString> m_activeActions;

@@ -221,6 +226,7 @@ private Q_SLOTS:
     void timerfdEventHandler();
     void onScreenLockerActiveChanged(bool active);
     void onResumeFromSuspend();
+    void checkScreensMirrored();
 };

 }
